  "Jedes Beispiel spielt zuerst eine Kadenz (<strong>I – vi – IV – V</strong>), damit dein Ohr weiß, wo „zu Hause“ ist. Nach einer Pause hörst du die jeweilige Stufe – und danach ihre natürliche <strong>Auflösung zur Tonika (Do)</strong>: Von <em>Do bis Fa</em> abwärts, ab <em>Sol</em> aufwärts!": {
    fr: "Chaque exemple commence par une cadence (<strong>I – vi – IV – V</strong>) pour ancrer votre oreille dans la tonalité. Après une courte pause, vous entendez le degré suivi de sa <strong>résolution naturelle vers Do</strong> — en descendant de <em>Do–Fa</em> et en montant de <em>Sol–Ti</em> !",
    es: "Cada ejemplo empieza con una cadencia (<strong>I – vi – IV – V</strong>) para anclar tu oído en la tonalidad. Tras una breve pausa, oyes el grado seguido de su <strong>resolución natural a Do</strong>: ¡bajando desde <em>Do–Fa</em> y subiendo desde <em>Sol–Ti</em>!",
    it: "Ogni esempio suona prima una cadenza (<strong>I – vi – IV – V</strong>), così il tuo orecchio capisce dov’è «casa». Dopo una breve pausa ascolti il grado — e subito dopo la sua naturale <strong>risoluzione alla tonica (Do)</strong>: scendendo da <em>Do a Fa</em>, salendo da <em>Sol</em> in su!",
    pl: "Każdy przykład zaczyna się od kadencji (<strong>I – vi – IV – V</strong>), aby ucho poczuło centrum tonalne. Po pauzie słyszysz stopień, a potem jego naturalne <strong>rozwiązanie do toniki (Do)</strong>: od <em>Do do Fa</em> w dół, od <em>Sol do Ti</em> w górę!",
    uk: "Кожен приклад спершу програє каданс (<strong>I – vi – IV – V</strong>), щоб налаштувати слух на тональність. Після короткої паузи звучить певний ступінь, а потім його природне <strong>розв’язання в тоніку (Do)</strong>: від <em>Do–Fa</em> вниз, а від <em>Sol–Ti</em> вгору!",
    ur: "ہر مثال پہلے ایک کیڈینس (<strong>I – vi – IV – V</strong>) بجاتی ہے تاکہ کان کو گھر (کلید) کا احساس ہو۔ مختصر وقفے کے بعد مطلوبہ درجہ اور پھر اس کا فطری <strong>حل ٹانک (Do)</strong> پر سنائی دیتا ہے: <em>Do سے Fa</em> نیچے کی طرف، اور <em>Sol</em> سے اوپر کی طرف!",
    tr: "Her örnek önce bir kadans (<strong>I – vi – IV – V</strong>) çalar, böylece kulağın “evin” neresi olduğunu bilir. Kısa bir aradan sonra ilgili dereceyi, ardından da <strong>toniğe (Do) doğal çözülmesini</strong> duyarsın: <em>Do’dan Fa’ya</em> inici, <em>Sol’den</em> itibaren çıkıcı!",
    ar: "يعزف كل مثال أولًا قفلة موسيقية (<strong>I – vi – IV – V</strong>) ليعرف سمعك أين «الموطن». بعد وقفة تسمع الدرجة المعنية – ثم <strong>حلّها الطبيعي نحو درجة القرار (Do)</strong>: من <em>Do إلى Fa</em> هبوطًا، ومن <em>Sol</em> صعودًا!"
  },
