  "Der F-Schlüssel markiert f (F3) auf der 4. Linie zwischen den beiden Punkten – Standard für Bass, Cello, Posaune &amp; Klavier (linke Hand).": {
    fr: "Place Fa3 (F3) sur la 4e ligne entre ses deux points — standard pour basse, violoncelle, trombone &amp; main gauche piano.",
    es: "Coloca Fa3 (F3) en la 4.ª línea, entre sus dos puntos: estándar para bajo, violonchelo, trombón &amp; mano izquierda del piano.",
    it: "La chiave di Fa indica il Fa3 (F3) sul 4° rigo, tra i due punti: lo standard per basso, violoncello, trombone e pianoforte (mano sinistra).",
    pl: "Wyznacza dźwięk f (F3) na 4. linii między dwiema kropkami — standard dla basu, wiolonczeli, puzonu i lewej ręki fortepianu.",
    uk: "Закріплює F3 на 4-й лінійці між двома крапками — стандарт для басу, віолончелі, тромбона й лівої руки фортепіано.",
    ur: "دو نقطوں کے بیچ چوتھی لائن پر F3 کو نشان زد کرتا ہے — باس، چیلّو، ٹرامبون اور پیانو (بایاں ہاتھ) کا معیار۔",
    tr: "Fa anahtarı iki nokta arasındaki 4. çizgide Fa3 (F3) sesini işaretler – bas, çello, trombon &amp; piyano (sol el) için standarttır.",
    ar: "يحدّد مفتاح فا النغمة f (F3) على الخط الرابع بين النقطتين – القياسي للباص، التشيلو، الترومبون &amp; البيانو (اليد اليسرى)."
  },
