  "Alle Noten gelten zunächst als Stammtöne (bei Stufe 4 mit ♯/♭ direkt vor einzelnen Noten).": {
    fr: "Toutes les notes sont naturelles au départ (avec ♯/♭ ponctuels au niveau 4).",
    es: "Al principio todas las notas son naturales (con ♯/♭ ocasionales en el nivel 4).",
    it: "All’inizio tutte le note sono naturali (nel livello 4 con ♯/♭ direttamente davanti alle singole note).",
    pl: "Wszystkie nuty są na początku naturalne (na poziomie 4 z ♯/♭ bezpośrednio przy pojedynczych nutach).",
    uk: "Усі ноти читаються як натуральні (на 4-му рівні трапляються ♯/♭ біля окремих нот).",
    ur: "تمام نوٹس خالص سُر شمار ہوتے ہیں جب تک لیول 4 میں کسی نوٹ سے پہلے ♯ یا ♭ نہ لگا ہو۔",
    tr: "Tüm notalar önce temel ses olarak okunur (Seviye 4’te tekil notaların önünde ♯/♭ bulunur).",
    ar: "تُعامل جميع النغمات مبدئيًا كنغمات أصلية (في المستوى 4 مع ♯/♭ مباشرة أمام النغمات الفردية)."
  },
  "Das Generalvorzeichen gilt für das ganze System: Achte bei betroffenen Stammlinien &amp; Räumen automatisch auf die schwarzen Tasten!": {
    fr: "L’armure s’applique à toute la portée : pensez aux touches noires pour les notes concernées !",
    es: "La armadura vale para todo el pentagrama: ¡piensa en las teclas negras para las notas afectadas!",
    it: "L’armatura di chiave vale per tutto il pentagramma: fai attenzione ai tasti neri per le note coinvolte!",
    pl: "Znaki przykluczowe działają na całą pięciolinię: pamiętaj o czarnych klawiszach dla zmienionych dźwięków!",
    uk: "Ключові знаки діють на весь нотний стан: не забувай натискати чорні клавіші для відповідних ступенів!",
    ur: "یہ کی سگنیچر پورے اسٹاف پر لاگو ہے: متاثرہ لائنوں اور خانوں پر خودکار کالی کنجیاں (شارپ/فلیٹ) بجائیں!",
    tr: "Donanım işareti tüm porte için geçerlidir: Etkilenen çizgi &amp; aralıklarda siyah tuşlara otomatik olarak dikkat et!",
    ar: "يسري دليل السلم على المدرج كاملًا: انتبه تلقائيًا للمفاتيح السوداء في الخطوط &amp; المسافات المتأثّرة!"
  },
