  "Der Rhythmus steht im Notensystem – ohne Vorspielen. Nach 1 Takt Vorzähler tippst du ihn zum Metronom auf das Pad.": {
    fr: "Le rythme est écrit sur la portée – sans démonstration. Après 1 mesure de décompte, tapez-le sur le pad avec le métronome.",
    es: "El ritmo está escrito en el pentagrama, sin demostración. Tras 1 compás de cuenta previa, tócalo en el pad con el metrónomo.",
    it: "Il ritmo è scritto sul pentagramma, senza ascolto preliminare. Dopo 1 battuta di conteggio, battilo sul pad a metronomo.",
    pl: "Rytm jest zapisany w nutach – bez przykładu. Po 1 takcie odliczania wystukaj go na padzie razem z metronomem.",
    uk: "Ритм записаний у нотах – без прикладу. Після 1 такту відліку вистукай його на педі разом із метрономом.",
    ur: "ردھم نوٹیشن میں لکھا ہے – بغیر نمونہ سنائے۔ 1 بار گنتی کے بعد میٹرونوم کے ساتھ پیڈ پر ٹیپ کریں۔",
    tr: "Ritim portede yazılıdır – ön dinleme olmadan. 1 ölçü ön sayımdan sonra metronomla pede dokunarak çalarsın.",
    ar: "يظهر الإيقاع على المدرج الموسيقي – دون عزف مسبق. بعد مازورة عدّ تمهيدي تنقره مع المترونوم على اللوحة."
  },
